# =============================================================================\n# DaVinci Resolve 18 / 19 / 21 Pro Auto-Batch Master Integration Script v2.5\n# Episode: DUMMY_VAR\n# Total Scenes: DUMMY_VAR Scenes\n# Generated on: DUMMY_VAR (DUMMY_VAR)\n# =============================================================================\n\nimport os\nimport sys\nimport time\nimport re\nimport glob\n\nprint("=" * 75)\nprint("🎬 [야담 AI 스튜디오] 다빈치 리졸브 v2.5 마스터 원클릭 자동화 배치 시작")\nprint(f"📌 [에피소드 제목]: DUMMY_VAR")\nprint(f"📌 [생성 일시]: DUMMY_VAR")\nprint(f"📌 [등록된 총 장면 수]: DUMMY_VAR개 씬")\nprint("=" * 75)\n\ndef get_resolve_instance():\n    try:\n        if "resolve" in globals() and globals()["resolve"] is not None:\n            return globals()["resolve"]\n    except Exception: pass\n    try:\n        if "resolve" in __builtins__ and __builtins__["resolve"] is not None:\n            return __builtins__["resolve"]\n    except Exception: pass\n    try:\n        if "GetResolve" in globals():\n            res = GetResolve()\n            if res: return res\n    except Exception: pass\n    try:\n        if "bmd" in globals() and hasattr(bmd, "scriptapp"):\n            res = bmd.scriptapp("Resolve")\n            if res: return res\n    except Exception: pass\n    script_paths = []\n    if sys.platform.startswith("win"):\n        script_paths.extend([\n            r"C:\\Program Files\\Blackmagic Design\\DaVinci Resolve\\Developer\\Scripting\\Modules",\n            os.path.expandvars(r"%PROGRAMFILES%\\Blackmagic Design\\DaVinci Resolve\\Developer\\Scripting\\Modules"),\n            os.path.expandvars(r"%PROGRAMDATA%\\Blackmagic Design\\DaVinci Resolve\\Support\\Developer\\Scripting\\Modules")\n        ])\n    elif sys.platform == "darwin":\n        script_paths.append("/Library/Application Support/Blackmagic Design/DaVinci Resolve/Developer/Scripting/Modules")\n    else:\n        script_paths.append("/opt/resolve/Developer/Scripting/Modules")\n    for path in script_paths:\n        if os.path.exists(path) and path not in sys.path:\n            sys.path.append(path)\n    try:\n        import DaVinciResolveScript as dvr_script\n        res = dvr_script.scriptapp("Resolve")\n        if res: return res\n    except Exception: pass\n    return None\n\nresolve = get_resolve_instance()\n\nif not resolve:\n    print("[❌ 오류] 다빈치 리졸브 엔진에 연결할 수 없습니다.")\n    print("💡 [실행 방법 안내]")\n    print("1. 다빈치 리졸브를 실행하고 편집할 프로젝트를 엽니다.")\n    print("2. 상단 메뉴: [Workspace] -> [Console] 창을 엽니다.")\n    print("3. 콘솔 창 상단 [Py3] 탭을 선택하고 이 스크립트를 붙여넣은 뒤 Enter를 누르세요!")\n    sys.exit(1)\n\npm = resolve.GetProjectManager()\nproj = pm.GetCurrentProject()\nif not proj:\n    proj = pm.CreateProject(f"Yadam_Auto_Timeline_{time.strftime('%Y%m%d_%H%M%S')}")\n    print("[INFO] 새 다빈치 프로젝트가 생성되었습니다.")\n\nmediaPool = proj.GetMediaPool()\nrootFolder = mediaPool.GetRootFolder()\n\nCUSTOM_ASSET_DIR = r""\n\ndef find_asset_folder():\n    if CUSTOM_ASSET_DIR and os.path.exists(CUSTOM_ASSET_DIR):\n        print(f"🎯 [사용자 지정 에셋 폴더]: {CUSTOM_ASSET_DIR}")\n        return os.path.abspath(CUSTOM_ASSET_DIR)\n\n    try:\n        if "__file__" in globals() and globals()["__file__"]:\n            py_dir = os.path.abspath(os.path.dirname(globals()["__file__"]))\n            if os.path.exists(py_dir) and not any(k in py_dir.lower() for k in ["blackmagic", "davinci resolve", "system32", "program files"]):\n                f_list = os.listdir(py_dir)\n                if any("scene_" in f.lower() or "cut_" in f.lower() or "supertonic" in f.lower() or "yadam" in f.lower() for f in f_list):\n                    print(f"🎯 [스크립트 위치 에셋 폴더 자동 선택]: {py_dir}")\n                    return py_dir\n    except Exception: pass\n\n    try:\n        import tkinter as tk\n        from tkinter import filedialog\n        root = tk.Tk()\n        root.withdraw()\n        root.attributes("-topmost", True)\n        root.update()\n        print("📂 [안내] 비디오/음성/이미지가 들어있는 작업 폴더를 선택해주세요...")\n        selected = filedialog.askdirectory(title="[야담 AI] 비디오/음성이 들어있는 작업 폴더를 선택하세요")\n        root.destroy()\n        if selected and os.path.exists(selected):\n            print(f"🎯 [선택된 작업 에셋 폴더]: {selected}")\n            return os.path.abspath(selected)\n    except Exception: pass\n\n    candidate_folders = []\n    search_roots = [\n        os.path.expanduser("~/Downloads"),\n        os.path.expanduser("~/Desktop"),\n        os.path.expanduser("~/Documents")\n    ]\n    for s_root in search_roots:\n        if not os.path.exists(s_root): continue\n        try:\n            for entry in os.scandir(s_root):\n                if entry.is_dir() and not entry.name.startswith("."):\n                    if "_yadam_stills_individual" in entry.name: continue\n                    candidate_folders.append(entry.path)\n                    try:\n                        for sub in os.scandir(entry.path):\n                            if sub.is_dir() and not sub.name.startswith("."):\n                                candidate_folders.append(sub.path)\n                    except Exception: pass\n        except Exception: pass\n\n    valid_candidates = []\n    for c_dir in set(candidate_folders):\n        if not os.path.exists(c_dir): continue\n        try: files = os.listdir(c_dir)\n        except Exception: continue\n\n        vid_files = [f for f in files if os.path.splitext(f)[1].lower() in [".mp4", ".mov", ".webm", ".mkv", ".m4v"]]\n        aud_files = [f for f in files if os.path.splitext(f)[1].lower() in [".mp3", ".wav", ".m4a", ".aac"]]\n        img_files = [f for f in files if os.path.splitext(f)[1].lower() in [".png", ".jpg", ".jpeg", ".webp"]]\n\n        has_scene_vid = any(re.search(r"(?:scene|cut|ltx)[_\\s-]*0*1\\.(mp4|mov|webm)", f.lower()) or f.lower().startswith("scene_001") for f in vid_files)\n        if has_scene_vid or (len(vid_files) >= 2) or (len(aud_files) >= 1 and (len(img_files) >= 2 or len(vid_files) >= 1)):\n            max_mtime = 0\n            for f in files:\n                ext = os.path.splitext(f)[1].lower()\n                if ext in [".png", ".jpg", ".jpeg", ".mp4", ".mov", ".webm", ".mp3", ".wav"]:\n                    fpath = os.path.join(c_dir, f)\n                    try:\n                        mt = os.path.getmtime(fpath)\n                        if mt > max_mtime: max_mtime = mt\n                    except Exception: pass\n            score = (len(vid_files) * 500) + (len(aud_files) * 100) + (len(img_files) * 2) + (max_mtime / 100000000.0)\n            if has_scene_vid: score += 5000\n            if "yadam" in os.path.basename(c_dir).lower(): score += 2000\n            valid_candidates.append((c_dir, score, max_mtime, len(vid_files), len(img_files), len(aud_files)))\n\n    if valid_candidates:\n        valid_candidates.sort(key=lambda x: (x[1], x[2]), reverse=True)\n        best_dir, score, best_time, v_c, i_c, a_c = valid_candidates[0]\n        time_str = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(best_time))\n        print(f"🎯 [에셋 폴더 자동 감지]: {best_dir}")\n        print(f"   (수정일시: {time_str} | 비디오: {v_c}개 | 이미지: {i_c}개 | 오디오: {a_c}개)")\n        return best_dir\n\n    return os.path.expanduser("~/Downloads")\n\nASSET_DIR = find_asset_folder()\nprint(f"📂 [최종 확정 에셋 경로]: {ASSET_DIR}")\n\nSCENES = [\n    {\n        "id": DUMMY_VAR,\n        "num_str": "DUMMY_VAR",\n        "num_short": "DUMMY_VAR",\n        "narration": "DUMMY_VAR",\n        "motion": "DUMMY_VAR",\n        "duration": DUMMY_VAR,\n        "srt_start": DUMMY_VAR,\n        "srt_end": DUMMY_VAR\n    },\n]\n\nmaster_timeline_name = f"Yadam_Timeline_{time.strftime('%Y%m%d_%H%M%S')}"\ntry:\n    proj.SetSetting("timelineResolutionWidth", "1920")\n    proj.SetSetting("timelineResolutionHeight", "1080")\n    proj.SetSetting("timelineFrameRate", "24.0")\n    proj.SetSetting("timelinePlaybackFrameRate", "24.0")\nexcept Exception: pass\n\nfps_val = 24.0\ntry:\n    fps_setting = float(proj.GetSetting("timelineFrameRate") or 24.0)\n    if fps_setting > 0: fps_val = fps_setting\nexcept Exception: pass\n\nbin_name = f"Yadam_{time.strftime('%Y%m%d_%H%M%S')}"\ntarget_bin = None\ntry:\n    target_bin = mediaPool.AddSubFolder(rootFolder, bin_name)\n    if target_bin:\n        mediaPool.SetCurrentFolder(target_bin)\n        print(f"📁 [미디어 풀 전용 빈 생성]: {bin_name}")\nexcept Exception:\n    target_bin = rootFolder\n\n# 1단계: 파일 탐색 및 장면별 최적 단일 에셋(동영상 최우선) 매칭\nscan_dirs = [ASSET_DIR]\nfor sub in ["scenes", "videos", "images", "audio", "voice", "subtitles", "cuts", "media"]:\n    sub_p = os.path.join(ASSET_DIR, sub)\n    if os.path.exists(sub_p) and sub_p not in scan_dirs: scan_dirs.append(sub_p)\n\nall_video_files = []\nall_image_files = []\nall_audio_files = []\nall_srt_files = []\n\nvid_exts = {".mp4", ".mov", ".webm", ".mkv", ".m4v", ".avi"}\nimg_exts = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}\naud_exts = {".mp3", ".wav", ".m4a", ".aac", ".flac", ".ogg"}\nsrt_exts = {".srt", ".vtt"}\n\nfor s_dir in scan_dirs:\n    try:\n        for root, dirs, files in os.walk(s_dir):\n            if "_yadam_stills_individual" in root: continue\n            for f in files:\n                ext = os.path.splitext(f)[1].lower()\n                fp = os.path.join(root, f)\n                try:\n                    mt = os.path.getmtime(fp)\n                    sz = os.path.getsize(fp)\n                    if sz <= 0: continue\n                    if ext in vid_exts: all_video_files.append((fp, f, mt, sz))\n                    elif ext in img_exts: all_image_files.append((fp, f, mt, sz))\n                    elif ext in aud_exts: all_audio_files.append((fp, f, mt, sz))\n                    elif ext in srt_exts: all_srt_files.append((fp, f, mt, sz))\n                except Exception: pass\n    except Exception: pass\n\ndef find_best_scene_file(s_id, s_str3, s_str2):\n    id_num = int(s_id)\n    # 1. 비디오 파일(MP4/MOV) 최우선 매칭\n    matched_vids = []\n    for fp, fn, mt, sz in all_video_files:\n        fn_l = fn.lower()\n        base_no_ext = os.path.splitext(fn_l)[0]\n        if base_no_ext in [f"scene_{s_str3}", f"scene_{s_str2}", f"scene_{id_num}", f"cut_{s_str3}", f"cut_{s_str2}", f"cut_{id_num}", f"ltx_{s_str3}", f"ltx_{s_str2}", f"ltx_{id_num}", f"{s_str3}", f"{s_str2}", str(id_num)]:\n            matched_vids.append((fp, 1000, mt))\n        elif fn_l.startswith(f"scene_{s_str3}") or fn_l.startswith(f"scene_{s_str2}") or fn_l.startswith(f"scene_{id_num}") or fn_l.startswith(f"cut_{s_str3}"):\n            matched_vids.append((fp, 800, mt))\n        elif re.search(rf'^(?:scene|cut|ltx|shot|clip)?[_\\s-]*0*{id_num}(?:[_\\s-].*)?$', base_no_ext):\n            matched_vids.append((fp, 600, mt))\n        elif f"_{s_str3}" in fn_l or f"_{s_str2}" in fn_l or f"-{s_str3}" in fn_l:\n            matched_vids.append((fp, 400, mt))\n    if matched_vids:\n        matched_vids.sort(key=lambda x: (x[1], x[2]), reverse=True)\n        return (matched_vids[0][0], True)\n\n    # 2. 비디오가 없을 때만 스틸 이미지 매칭 (중복 임포트 완전 방지)\n    matched_imgs = []\n    for fp, fn, mt, sz in all_image_files:\n        fn_l = fn.lower()\n        base_no_ext = os.path.splitext(fn_l)[0]\n        if base_no_ext in [f"scene_{s_str3}", f"scene_{s_str2}", f"scene_{id_num}", f"cut_{s_str3}", f"cut_{s_str2}", f"cut_{id_num}", f"ltx_{s_str3}", f"ltx_{s_str2}", f"ltx_{id_num}", f"{s_str3}", f"{s_str2}", str(id_num)]:\n            matched_imgs.append((fp, 1000, mt))\n        elif fn_l.startswith(f"scene_{s_str3}") or fn_l.startswith(f"scene_{s_str2}") or fn_l.startswith(f"scene_{id_num}"):\n            matched_imgs.append((fp, 800, mt))\n        elif re.search(rf'^(?:scene|cut|ltx|shot|clip)?[_\\s-]*0*{id_num}(?:[_\\s-].*)?$', base_no_ext):\n            matched_imgs.append((fp, 600, mt))\n        elif f"_{s_str3}" in fn_l or f"_{s_str2}" in fn_l or f"-{s_str3}" in fn_l:\n            matched_imgs.append((fp, 400, mt))\n    if matched_imgs:\n        matched_imgs.sort(key=lambda x: (x[1], x[2]), reverse=True)\n        return (matched_imgs[0][0], False)\n    return (None, False)\n\nprepared_scene_files = {}\nvid_count = 0\nimg_count = 0\nfor sc in SCENES:\n    s_id = sc["id"]\n    fp, is_v = find_best_scene_file(s_id, sc["num_str"], sc["num_short"])\n    if fp:\n        prepared_scene_files[s_id] = (fp, is_v)\n        if is_v: vid_count += 1\n        else: img_count += 1\n\nprint(f"📊 [에셋 매칭 결과]: 총 {len(SCENES)}개 씬 중 비디오 {vid_count}개, 스틸이미지 {img_count}개 매칭 완료!")\n\n# ★ 중요: 매칭된 고유 파일만 미디어 풀에 단일 임포트 (빨간색 No Image/미디어 오프라인 원천 차단)\nunique_scene_paths = list(set([v[0] for v in prepared_scene_files.values()]))\nimported_clip_map = {}\nif unique_scene_paths:\n    try:\n        imported_res = mediaPool.ImportMedia(unique_scene_paths)\n        if imported_res:\n            for c in imported_res:\n                try:\n                    p_info = c.GetClipProperty()\n                    c_path = os.path.normpath(p_info.get("File Path", "") if isinstance(p_info, dict) else "").lower()\n                    if c_path: imported_clip_map[c_path] = c\n                except Exception: pass\n    except Exception: pass\n\nfor sc in SCENES:\n    s_id = sc["id"]\n    if s_id in prepared_scene_files:\n        fp = prepared_scene_files[s_id][0]\n        fp_norm = os.path.normpath(fp).lower()\n        if fp_norm in imported_clip_map:\n            sc["media_item"] = imported_clip_map[fp_norm]\n        else:\n            try:\n                res_single = mediaPool.ImportMedia([fp])\n                if res_single: sc["media_item"] = res_single[0]\n            except Exception: pass\n\n# 2단계: 성우 음성 (WAV / MP3) 및 자막 파일 (.SRT) 정밀 탐색\nmaster_audio_item = None\nmaster_audio_path = None\nif all_audio_files:\n    def aud_rank(item):\n        fp, fn, mt, sz = item\n        is_wav = 1000 if fn.lower().endswith(".wav") else 0\n        kw = 100 if any(k in fn.lower() for k in ["supertonic", "yadam", "tts", "voice", "audio"]) else 10\n        return (is_wav + kw, mt, sz)\n    all_audio_files.sort(key=aud_rank, reverse=True)\n    master_audio_path = all_audio_files[0][0]\n    print(f"🎙️ [성우 나레이션 오디오 감지]: {os.path.basename(master_audio_path)}")\n    try:\n        a_res = mediaPool.ImportMedia([master_audio_path])\n        if a_res: master_audio_item = a_res[0]\n    except Exception: pass\n\n# 로컬 SRT 파싱\nlocal_srt_parsed = []\nif all_srt_files:\n    all_srt_files.sort(key=lambda x: (100 if "supertonic" in x[1].lower() or "yadam" in x[1].lower() else 10, x[2]), reverse=True)\n    chosen_srt = all_srt_files[0][0]\n    print(f"📝 [로컬 SRT 자막 감지]: {os.path.basename(chosen_srt)}")\n    try:\n        with open(chosen_srt, "r", encoding="utf-8", errors="ignore") as sf:\n            content = sf.read().replace("\ufeff", "").replace("\r\n", "\n").replace("\r", "\n")\n            blocks = re.split(r"\n\s*\n", content.strip())\n            for b in blocks:\n                lines = [l.strip() for l in b.split("\n") if l.strip()]\n                if len(lines) >= 2 and "-->" in lines[1]:\n                    tc_p = lines[1].split("-->")\n                    def p_tc(v):\n                        v = v.strip().replace(",", ".")\n                        p = v.split(":")\n                        if len(p) == 3: return float(p[0])*3600 + float(p[1])*60 + float(p[2])\n                        return float(v)\n                    s_s = p_tc(tc_p[0])\n                    e_s = p_tc(tc_p[1])\n                    txt = " ".join(lines[2:])\n                    local_srt_parsed.append({"start": s_s, "end": e_s, "text": txt})\n        print(f"   (총 {len(local_srt_parsed)}개 자막 타임코드 파싱 완료)")\n    except Exception: pass\n\n# 3단계: 나레이션 오디오 및 씬별 타임코드 정밀 계산\ntotal_audio_frames = 0\nif master_audio_item:\n    try:\n        pf = master_audio_item.GetClipProperty("Frames")\n        if pf and int(pf) > 0: total_audio_frames = int(pf)\n    except Exception: pass\n\nif total_audio_frames <= 0 and local_srt_parsed:\n    total_audio_frames = int(local_srt_parsed[-1]["end"] * fps_val)\nif total_audio_frames <= 0 and master_audio_path and os.path.exists(master_audio_path):\n    try:\n        if master_audio_path.lower().endswith(".wav"):\n            import wave\n            with wave.open(master_audio_path, "rb") as wf:\n                r = wf.getframerate()\n                f = wf.getnframes()\n                if r > 0: total_audio_frames = int((f / float(r)) * fps_val)\n        elif master_audio_path.lower().endswith(".mp3"):\n            sz = os.path.getsize(master_audio_path)\n            est_sec = sz / 20000.0\n            if est_sec > 10: total_audio_frames = int(est_sec * fps_val)\n    except Exception: pass\n\nscene_start_frames = []\nscene_durations_frames = []\nscene_durations_sec = []\n\nif local_srt_parsed and len(local_srt_parsed) == len(SCENES):\n    for sc, srt_item in zip(SCENES, local_srt_parsed):\n        s_f = int(srt_item["start"] * fps_val)\n        e_f = int(srt_item["end"] * fps_val)\n        d_f = max(e_f - s_f, int(1.0 * fps_val))\n        scene_start_frames.append(s_f)\n        scene_durations_frames.append(d_f)\n        scene_durations_sec.append(d_f / fps_val)\nelif local_srt_parsed:\n    srt_i = 0\n    t_srts = len(local_srt_parsed)\n    for sc_idx, sc in enumerate(SCENES):\n        if srt_i >= t_srts:\n            prev_end = scene_start_frames[-1] + scene_durations_frames[-1] if scene_start_frames else 0\n            s_f = prev_end\n            d_f = int(float(sc.get("duration", 10.0)) * fps_val)\n        else:\n            f_st = local_srt_parsed[srt_i]["start"]\n            l_en = local_srt_parsed[srt_i]["end"]\n            srt_i += 1\n            s_f = int(f_st * fps_val)\n            d_f = max(int((l_en - f_st) * fps_val), int(1.0 * fps_val))\n        scene_start_frames.append(s_f)\n        scene_durations_frames.append(d_f)\n        scene_durations_sec.append(d_f / fps_val)\nelif total_audio_frames > 0 and len(SCENES) > 0:\n    weights = [max(len(sc.get("narration", "").strip()), 10) for sc in SCENES]\n    total_w = sum(weights) or 1.0\n    c_f = 0\n    alloc = 0\n    for i, w in enumerate(weights):\n        if i == len(weights) - 1: f_len = max(total_audio_frames - alloc, int(1.0 * fps_val))\n        else: f_len = max(int((w / total_w) * total_audio_frames), int(1.0 * fps_val))\n        scene_start_frames.append(c_f)\n        scene_durations_frames.append(f_len)\n        scene_durations_sec.append(f_len / fps_val)\n        c_f += f_len\n        alloc += f_len\nelse:\n    c_f = 0\n    for sc in SCENES:\n        f_len = int(float(sc.get("duration", 10.0)) * fps_val)\n        scene_start_frames.append(c_f)\n        scene_durations_frames.append(f_len)\n        scene_durations_sec.append(f_len / fps_val)\n        c_f += f_len\n\n# 갭(Gap) 제거: 다음 씬 시작점까지 100% 밀착 연장\nfor idx in range(len(SCENES)):\n    if idx < len(SCENES) - 1:\n        nxt = scene_start_frames[idx + 1]\n        if nxt > scene_start_frames[idx]:\n            scene_durations_frames[idx] = nxt - scene_start_frames[idx]\n            scene_durations_sec[idx] = scene_durations_frames[idx] / fps_val\n    else:\n        if total_audio_frames > 0 and total_audio_frames > scene_start_frames[idx]:\n            scene_durations_frames[idx] = max(total_audio_frames - scene_start_frames[idx], scene_durations_frames[idx])\n            scene_durations_sec[idx] = scene_durations_frames[idx] / fps_val\n\n# 4단계: 다빈치 네이티브 API 기반 타임라인 직접 생성 (XML 파싱 오프라인 오류 100% 방지)\ntry: resolve.OpenPage("edit")\nexcept Exception: pass\n\nordered_clips = [sc["media_item"] for sc in SCENES if sc.get("media_item")]\ntimeline = None\ntimeline_start_frame = 86400\n\ntry:\n    timeline = mediaPool.CreateEmptyTimeline(master_timeline_name)\n    if timeline:\n        proj.SetCurrentTimeline(timeline)\n        try: timeline.SetCurrentTimecode("01:00:00:00")\n        except Exception: pass\n        timeline_start_frame = timeline.GetStartFrame() or 86400\n        for idx, sc in enumerate(SCENES):\n            clp = sc.get("media_item")\n            if clp:\n                st_f = scene_start_frames[idx] if idx < len(scene_start_frames) else 0\n                du_f = scene_durations_frames[idx] if idx < len(scene_durations_frames) else int(10.0 * fps_val)\n                clip_dict = {\n                    "mediaPoolItem": clp,\n                    "startFrame": 0,\n                    "endFrame": du_f,\n                    "recordFrame": timeline_start_frame + st_f\n                }\n                try: mediaPool.AppendToTimeline([clip_dict])\n                except Exception:\n                    try: mediaPool.AppendToTimeline([clp])\n                    except Exception: pass\n        print(f"🎬 [네이티브 타임라인 생성 성공]: {len(ordered_clips)}개 클립이 V1 트랙에 정밀 배치되었습니다.")\nexcept Exception as t_err:\n    print(f"[타임라인 생성 알림]: {t_err}")\n\nif not timeline and ordered_clips:\n    try:\n        timeline = mediaPool.CreateTimelineFromClips(master_timeline_name, ordered_clips)\n        if timeline:\n            proj.SetCurrentTimeline(timeline)\n            print("🎬 [CreateTimelineFromClips 일괄 생성 성공]")\n    except Exception: pass\n\nif not timeline: timeline = proj.GetCurrentTimeline()\n\nif timeline:\n    proj.SetCurrentTimeline(timeline)\n    timeline_start_frame = timeline.GetStartFrame() or 86400\n    try: timeline.SetCurrentTimecode("01:00:00:00")\n    except Exception: pass\n\n    # A1 트랙: 성우 나레이션 오디오 배치 (01:00:00:00 시작점 직결)\n    if master_audio_item:\n        try:\n            a_dur = total_audio_frames if total_audio_frames > 0 else (scene_start_frames[-1] + scene_durations_frames[-1] if scene_durations_frames else 86400)\n            a_info = {\n                "mediaPoolItem": master_audio_item,\n                "startFrame": 0,\n                "endFrame": a_dur,\n                "recordFrame": timeline_start_frame,\n                "mediaType": 2\n            }\n            res_a = None\n            try: res_a = mediaPool.AppendToTimeline([a_info])\n            except Exception: pass\n            if not res_a:\n                try: res_a = mediaPool.AppendToTimeline([master_audio_item])\n                except Exception: pass\n            if res_a:\n                print("🎙️ [나레이션 오디오 트랙 배치 완료]: 01:00:00:00 시작점에 정밀 등록되었습니다.")\n        except Exception as a_err:\n            print(f"[오디오 배치 알림]: {a_err}")\n\n# 5단계: 다빈치 01:00:00:00 타임라인 전용 자막 파일 생성\ndavinci_srt_path = os.path.join(ASSET_DIR, "yadam_subtitles_01_davinci.srt")\nstandard_srt_path = os.path.join(ASSET_DIR, "yadam_subtitles_00_standard.srt")\ntry:\n    with open(davinci_srt_path, "w", encoding="utf-8") as f1:\n        f1.write("""DUMMY_VAR""")\n    print(f"📝 [다빈치 01:00:00:00 전용 자막 생성]: {davinci_srt_path}")\n    with open(standard_srt_path, "w", encoding="utf-8") as f2:\n        f2.write("""DUMMY_VAR""")\n    print(f"📝 [표준 00:00:00 자막 생성]: {standard_srt_path}")\nexcept Exception as s_err:\n    print(f"[자막 파일 생성 알림]: {s_err}")\n\nif os.path.exists(davinci_srt_path) and hasattr(timeline, "ImportSubtitle"):\n    try: timeline.ImportSubtitle(davinci_srt_path)\n    except Exception: pass\n\nprint("\n" + "=" * 75)\nprint("🎉 [완료] 다빈치 리졸브 마스터 타임라인 자동 생성이 성공적으로 완료되었습니다!")\nprint("-" * 75)\nprint("💡 [3대 문제 해결 체크포인트]")\nprint("1. [자막 등록]: 상단 메뉴 [File] -> [Import] -> [Subtitle...] 에서")\nprint("   'yadam_subtitles_01_davinci.srt' 파일을 선택하시면 ST1 트랙에 즉시 나타납니다.")\nprint("2. [오프라인 방지]: 동영상이 있는 씬은 이미지를 제외하여 빨간색 클립이 생기지 않습니다.")\nprint("3. [오디오 파형]: 파형이 안 보이면 타임라인 좌측 상단 [Timeline View Options]")\nprint("   (네모 3개 아이콘)을 클릭하고 [Audio Waveform] 버튼을 활성화하세요!")\nprint("=" * 75 + "\n")\n